<?php
declare(strict_types=1);namespace MiniErp\Platform;use PDO;use RuntimeException;use Throwable;final class MultiTenantMigrationExecutor{public function __construct(private PDO $server,private array $dbConfig,private string $backupRoot,private MultiTenantOperationRepository $operations){}public function execute(string $operationId,array $tenant,array $migration):array{$id=(int)$tenant['tenant_id'];$db=(string)$tenant['db_name'];if(!preg_match('/^mini_erp_tenant_[1-9][0-9]*$/',$db)||$db!=='mini_erp_tenant_'.$id)throw new RuntimeException('Banco nÃ£o corresponde ao tenant resolvido.');if($migration['target']!=='TENANT'||!$migration['approved']||in_array($migration['risk'],['DESTRUCTIVE','MANUAL_REVIEW'],true))return['status'=>'BLOCKED'];if(!hash_equals($migration['checksum'],hash_file('sha256',$migration['path'])))return['status'=>'CHECKSUM_MISMATCH'];$this->operations->addTarget($operationId,$id,$db,'PENDING');$started=microtime(true);try{$this->operations->target($operationId,$id,'BACKING_UP');$backup=$this->backup($operationId,$id,$db,$migration['migration_id']);$this->operations->target($operationId,$id,'BACKUP_OK',$backup);$lock='mini_erp_platform_migration_'.$id;$s=$this->server->query('SELECT GET_LOCK('.$this->server->quote($lock).',0)');if((int)$s->fetchColumn()!==1){$this->operations->target($operationId,$id,'BLOCKED',['error_message'=>'LOCKED']);return['status'=>'LOCKED'] ;}try{$this->operations->target($operationId,$id,'RUNNING');$pdo=$this->tenant($db);$sql=(string)file_get_contents($migration['path']);foreach(array_filter(array_map('trim',preg_split('/;\s*(?:\R|$)/',$sql)?:[])) as $statement)$pdo->exec($statement);$valid=$migration['expected_table']?(bool)$pdo->query('SHOW TABLES LIKE '.$pdo->quote($migration['expected_table']))->fetchColumn():true;if(!$valid){$this->operations->target($operationId,$id,'VALIDATION_FAILED',['validation_json'=>'{"valid":false}']);return['status'=>'VALIDATION_FAILED'];}$duration=(int)((microtime(true)-$started)*1000);$h=$pdo->prepare("INSERT INTO tenant_schema_migrations(migration_id,checksum,execution_status,duration_ms,operator_source) VALUES(?,?,'SUCCESS',?,'PLATFORM_MULTI_TENANT') ON DUPLICATE KEY UPDATE checksum=VALUES(checksum),execution_status='SUCCESS',duration_ms=VALUES(duration_ms),operator_source='PLATFORM_MULTI_TENANT'");$h->execute([$migration['migration_id'],$migration['checksum'],$duration]);$this->operations->target($operationId,$id,'SUCCESS',['duration_ms'=>$duration,'validation_json'=>'{"valid":true}']);return['status'=>'SUCCESS','backup'=>$backup];}finally{$this->server->query('SELECT RELEASE_LOCK('.$this->server->quote($lock).')');}}catch(Throwable $e){$status=str_contains($e->getMessage(),'mysqldump')?'BACKUP_FAILED':'FAILED';$this->operations->target($operationId,$id,$status,['error_message'=>substr($e->getMessage(),0,1000)]);return['status'=>$status,'error'=>$e->getMessage()];}}private function backup(string $op,int $tenant,string $db,string $migration):array{$dir=rtrim($this->backupRoot,'/\\').DIRECTORY_SEPARATOR.$op;if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('BACKUP_FAILED mkdir');$path=$dir.DIRECTORY_SEPARATOR.'tenant-'.$tenant.'-before-'.preg_replace('/[^A-Za-z0-9_.-]/','_',$migration).'.sql';$bin='C:/xampp/mysql/bin/mysqldump.exe';$cmd=[$bin,'-h',(string)$this->dbConfig['host'],'-P',(string)$this->dbConfig['port'],'-u',(string)$this->dbConfig['username'],'--single-transaction','--routines','--triggers','--events','--result-file='.$path,$db];$env=null;if((string)$this->dbConfig['password']!=='')$env=['MYSQL_PWD'=>(string)$this->dbConfig['password']];$p=proc_open($cmd,[1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);if(!is_resource($p))throw new RuntimeException('BACKUP_FAILED mysqldump start');$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||!is_file($path)||filesize($path)===0)throw new RuntimeException('BACKUP_FAILED mysqldump '.trim($err));return['backup_path'=>$path,'backup_size'=>filesize($path),'backup_sha256'=>hash_file('sha256',$path)];}private function tenant(string $db):PDO{return new PDO(sprintf('mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4',$this->dbConfig['host'],$this->dbConfig['port'],$db),$this->dbConfig['username'],$this->dbConfig['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}}
